ACTIONS = [('key', 5)]


@dataclass
class State:
    """One field per instance per observation the word table names."""
    Marker_pos: object = (1, 1)
    Marker_color: object = 9
    Unused_pos: object = (1, 5)
    Unused_color: object = 1
    Unused_present: object = True
    Spent_pos: object = (0, 0)
    Spent_color: object = 2
    Spent_present: object = False

    def copy(self):
        return replace(self)

    def key(self):
        return (self.Marker_pos, self.Marker_color, self.Unused_pos, self.Unused_color, self.Unused_present, self.Spent_pos, self.Spent_color, self.Spent_present,)


def _neighbour(cell, direction):
    dr, dc = DIRECTIONS[direction]
    return (cell[0] + dr, cell[1] + dc)


def _in_bounds(cell):
    return 0 <= cell[0] < GRID[0] and 0 <= cell[1] < GRID[1]


def _adjacent(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1


def render(state):
    """The manual drawn back onto a frame."""
    grid = [list(row) for row in BOARD]
    if True:
        r, c = state.Marker_pos
        grid[r][c] = state.Marker_color
    if state.Unused_present:
        r, c = state.Unused_pos
        grid[r][c] = state.Unused_color
    if state.Spent_present:
        r, c = state.Spent_pos
        grid[r][c] = state.Spent_color
    return grid


def _cell_colour(state, cell):
    if not _in_bounds(cell):
        return None
    return render(state)[cell[0]][cell[1]]


def _free(state, cell):
    return _cell_colour(state, cell) == BACKGROUND


def occupancy(state):
    """The frame as a bitstring — the view a pagoda weight sees."""
    return ''.join('0' if v == BACKGROUND else '1'
                   for row in render(state) for v in row)


def _guard_key5_advances_marker(state, action):
    """key5_advances_marker  [ev: t5  cov: 1/1]"""
    if action != ('key', 5): return False
    if not (_cell_colour(state, LANDMARKS['hud_slot_b']) == 1): return False
    return True


def _effect_key5_advances_marker(state):
    state.Marker_pos = LANDMARKS['hud_slot_b']


def _guard_key5_marks_slot_a_spent(state, action):
    """key5_marks_slot_a_spent  [ev: t5  cov: 1/1]"""
    if action != ('key', 5): return False
    if not (_cell_colour(state, LANDMARKS['hud_slot_a']) == 9): return False
    return True


def _effect_key5_marks_slot_a_spent(state):
    state.Spent_present = True


def _guard_key5_consumes_slot_b(state, action):
    """key5_consumes_slot_b  [ev: t5  cov: 1/1]"""
    if action != ('key', 5): return False
    if not (_cell_colour(state, LANDMARKS['hud_slot_b']) == 1): return False
    return True


def _effect_key5_consumes_slot_b(state):
    state.Unused_present = False


RULES = [
    ('key5_advances_marker', _guard_key5_advances_marker, _effect_key5_advances_marker, ['Marker']),
    ('key5_marks_slot_a_spent', _guard_key5_marks_slot_a_spent, _effect_key5_marks_slot_a_spent, ['Spent']),
    ('key5_consumes_slot_b', _guard_key5_consumes_slot_b, _effect_key5_consumes_slot_b, ['Unused']),
]


class AmbiguousTransition(Exception):
    """Two rules claimed one object: `conflict exclusive` is violated."""


def step(state, action):
    """One action, one successor, per the manual's `semantics:`.

    frame persist        -- an object no firing rule touches is
                            unchanged, which is what makes this total.
    conflict exclusive   -- two rules claiming one object is an error,
                            not a precedence question.
    cascade single_frame -- every guard reads `state`, never the
                            partially updated result.
    """
    result = state.copy()
    claimed = {}
    for name, guard, effect, objs in RULES:
        if not guard(state, action):
            continue
        for obj in objs:
            if obj in claimed:
                raise AmbiguousTransition(
                    '%s and %s both fire on %s for %s'
                    % (claimed[obj], name, action, obj))
            claimed[obj] = name
        effect(result)
    return result


def fired(state, action):
    return [n for n, g, _e, _o in RULES if g(state, action)]


def is_goal(state):
    return False


def simulate(initial, actions):
    states = [initial]
    current = initial
    for action in actions:
        current = step(current, action)
        states.append(current)
    return states


def initial_state():
    return State(
        Marker_pos=(1, 1),
        Marker_color=9,
        Unused_pos=(1, 5),
        Unused_color=1,
        Unused_present=True,
        Spent_pos=(0, 0),
        Spent_color=2,
        Spent_present=False,
    )
